#[cfg(test)]
pub(crate) async fn wait_for(&self, predicate: impl Fn(&Snapshot) -> bool) {
    loop {
        let notified = self.changed.notified();
        tokio::pin!(notified);
        notified.as_mut().enable();
        if predicate(&self.snapshot()) {
            return;
        }
        notified.await;
    }
}

